INSERT INTO legal_concepts (id, concept, category, subcategory, definition_simple, real_example, regulation, jurisprudence, video_url, key_points) VALUES
('DP-001', 'Capacidad Procesal', 'Derecho Procesal', 'Reglas Comunes a Todo Procedimiento', 'Aptitud legal para comparecer válidamente en juicio, sea por sí o mediante representante legal. Difiere de la capacidad para ser parte, que es la idoneidad para figurar como sujeto en el proceso (toda persona natural o jurídica la tiene); la capacidad procesal exige mayoría de edad o habilitación legal.', 'Ej.: Un menor de edad debe litigar representado por su tutor, careciendo de capacidad procesal propia.', 'Art. 7 Código de Procedimiento Civil (CPC) (los incapaces solo actúan por representante)', '', '', '["Se discute si la capacidad procesal es un presupuesto de existencia del proceso (vicio de incapacidad genera nulidad) o solo un requisito subsanable", "Doctrina unánime la considera requisito indispensable, pero la jurisprudencia ha permitido subsanar representaciones defectuosas durante el juicio para evitar nulidades innecesarias ."]'),
('DP-002', 'Litisconsorcio', 'Derecho Procesal', 'Reglas Comunes a Todo Procedimiento', 'Situación en que varias personas actúan como demandantes o demandados en un mismo juicio, compartiendo un interés jurídico común. Puede ser voluntario (partes deciden litigar conjuntamente) o necesario (la ley exige la presencia de todos los interesados).', 'Ej.: Dos copropietarios presentan juntos una demanda (litisconsorcio activo) o un deudor y su codeudor son demandados simultáneamente (litisconsorcio pasivo) en un mismo proceso.', 'Art. 18 CPC (autoriza litigar conjuntamente cuando la acción emane de un mismo hecho o derecho)', '', '', '["Debate doctrinal sobre litisconsorcio necesario: algunos sostienen que la sentencia es nula si no comparecen todos los sujetos jurídicamente ligados (p. ej., todos los cotitulares de un derecho real)", "Otros estiman que el juez puede instar la integración de tales partes ausentes antes de fallar, privilegiando la economía procesal sobre formalidades ."]'),
('DP-003', 'Patrocinio y Poder', 'Derecho Procesal', 'Reglas Comunes a Todo Procedimiento', 'Regla general que exige que las partes comparezcan en juicio representadas por un abogado habilitado (patrocinio) y mediante un mandato judicial otorgado (poder). El patrocinio se acredita con la firma del abogado en los escritos, y el poder con el instrumento que faculta al mandatario para actuar en nombre de la parte.', 'Ej.: En una demanda civil de mayor cuantía, el demandante otorga poder ante notario a un abogado y este patrocina el escrito inicial, cumpliendo con la exigencia legal.', 'Arts. 1, 4, 6 CPC (obligatoriedad de comparecer por medio de abogado patrocinante y mandatario con poder suficiente)', '', '', '["Tensión práctica: la ausencia de poder o patrocinio válido puede llevar to la nulidad de lo obrado, pero la jurisprudencia tiende a conceder oportunidades de subsanar (aportar poder dentro de plazo) para no sacrificar el fondo por defectos formales", "Discusión doctrinal sobre si el vicio de falta de patrocinio es saneable o causa de inadmisibilidad radical de la demanda ."]'),
('DP-004', 'Notificaciones', 'Derecho Procesal', 'Reglas Comunes a Todo Procedimiento', 'Acto formal por el cual se comunica a las partes el contenido de las resoluciones judiciales, para que produzcan efecto. La primera notificación de la demanda debe ser personal al demandado, y en general ninguna resolución genera efecto si no ha sido notificada conforme a la ley.', 'Ej.: El auto de apertura de prueba se notifica por cédula al abogado del demandado en su domicilio registrado. Solo desde esa notificación comienza a correr el plazo probatorio.', 'Arts. 38 y ss. CPC (toda resolución surte efecto con notificación legal; requisitos de notificación personal, por cédula, por avisos, etc.)', 'Corte Suprema, 02.07.2019, Rol 13.122-2019 (anuló todo lo obrado tras notificación defectuosa, reiterando que la notificación inválida vulnera la bilateralidad de la audiencia)', '', '["Se contraponen posturas: estricta sujeción a las formalidades (vicios en notificaciones acarrean nulidad ipso iure) vs. la postura teleológica que exige demostrar indefensión efectiva para anular por notificación viciada", "La jurisprudencia reciente exige analizar caso a caso si la notificación defectuosa causó perjuicio, modulando así la sanción de nulidad procesal."]'),
('DP-005', 'Plazos Procesales', 'Derecho Procesal', 'Reglas Comunes a Todo Procedimiento', 'Periodos de tiempo fijados por la ley o el tribunal para realizar actos procesales. Por regla general son fatales (su inobservancia extingue el derecho a actuar) y se computan en días hábiles judiciales. Comienzan a correr desde la medianoche del día de la notificación respectiva, salvo régimen especial de ampliación por distancia.', 'Ej.: En un juicio ordinario civil, el demandado tiene 15 días para contestar la demanda si fue notificado dentro del territorio jurisdiccional del tribunal; vencido ese plazo sin contestación, queda en rebeldía.', 'Arts. 258-259 CPC (plazos para contestar demanda según distancia); Art. 66 CPC (plazos fatales y prorrogables)', '', '', '["Crítica recurrente: la fatalidad estricta de los plazos puede chocar con la tutela judicial efectiva. Tribunales han flexibilizado plazos solo en casos excepcionales (fuerza mayor, artículo 79 CPC)", "Doctrina propone instaurar un régimen de “plazos interrumpibles” o conceder al juez facultad de extensión por razones fundadas, lo cual se enfrenta al principio de certeza y preclusión propio de la seguridad procesal."]'),
('DP-006', 'Jurisdicción', 'Derecho Procesal', 'Disposiciones Orgánicas (Tribunales)', 'Poder-deber del Estado, radicado exclusivamente en los tribunales de justicia, de conocer, juzgar y hacer cumplir lo juzgado en causas de naturaleza contenciosa o asuntos no contenciosos sometidos a su conocimiento. Es de orden público y emana de la soberanía (Art. 76 Constitución).', 'Ej.: Un conflicto civil por incumplimiento contractual es resuelto por el juez civil competente, ejerciendo la jurisdicción que la ley le confiere.', 'Art. 1 Código Orgánico de Tribunales (COT)', '', '', '["Se contrapone al ejercicio privado de autotutela: la jurisdicción monopoliza la solución de litigios, pero su alcance es limitado por la inmunidad soberana extranjera o fueros especiales (crítica: ciertos actos administrativos con efecto jurisdiccional podrían lesionar la exclusividad)", "Discusión sobre “jurisdicción voluntaria”: algunos la excluyen de la función jurisdiccional por no haber litigio, mientras otros la incluyen por involucrar actuación de tribunales."]'),
('DP-007', 'Competencia', 'Derecho Procesal', 'Disposiciones Orgánicas (Tribunales)', 'Ámbito dentro del cual cada tribunal puede ejercer jurisdicción, determinado por factores establecidos en la ley: materia (asunto de que se trata), cuantía (valor económico), territorio (lugar), grado (instancia) y fuero (privilegio de determinadas autoridades). La competencia absoluta refiere a materia, cuantía y fuero; la relativa al territorio del tribunal.', 'Ej.: Un juicio civil de cobro por ~$5.000 USD se ventila ante un Juzgado de Letras en lo Civil (materia civil, cuantía sobre 10 UTM), con competencia en la comuna del domicilio del demandado (territorio).', 'Arts. 108-115 COT (competencia por materia y cuantía); Arts. 134-139 COT (reglas de competencia territorial y prórroga)', 'CS, 03.05.2016, Rol 11.883-2015 (casó sentencia por tribunal incompetente, declarando nulidad de lo actuado por vulneración de competencia absoluta)', '', '["Existe tensión entre rigidez y flexibilidad: la incompetencia absoluta es de orden público (vicio insanable, puede ser declarada de oficio incluso en segunda instancia), mientras la incompetencia relativa debe alegarse oportunamente o se entiende prorrogada por tácita sumisión", "La doctrina critica la complejidad de las reglas de competencia territorial en un contexto de modernización digital, proponiendo simplificar radicación foral por territorio."]'),
('DP-008', 'Juez Natural', 'Derecho Procesal', 'Disposiciones Orgánicas (Tribunales)', 'Principio fundamental según el cual toda persona tiene derecho a ser juzgada por tribunales ordinarios previamente establecidos por la ley, competentes para la materia y territorio del caso. Se prohíben los tribunales de excepción o comisiones especiales creados ex post hecho.', 'Ej.: Un funcionario acusado de un delito común será juzgado por el tribunal penal ordinario que señala la ley y no por una comisión ad-hoc. Del mismo modo, un civil no puede ser juzgado por un tribunal militar si la ley no lo contempla (resguardo del juez natural).', 'Art. 19 N°3 Constitución Política; Art. 2 COT (proscribe comisiones especiales, exige tribunal establecido con anterioridad)', '', '', '["Conflicto notorio en estados de excepción: algunos han intentado crear tribunales especiales (v.g. consejos de guerra, tribunales militares a civiles); la doctrina y la jurisprudencia los han declarado inconstitucionales por infringir el juez natural", "Asimismo, se debate si la designación de ministros visitadores o jueces suplentes para descongestionar causas viola el principio; la Corte Suprema ha resuelto que, mientras estén autorizados por ley con antelación, no se vulnera la garantía del juez natural ."]'),
('DP-009', 'Tribunales Ordinarios vs. Especiales', 'Derecho Procesal', 'Disposiciones Orgánicas (Tribunales)', 'Los tribunales ordinarios son aquellos del Poder Judicial con competencia general (Corte Suprema, Cortes de Apelaciones, tribunales de juicio oral, juzgados de letras y de garantía), mientras que los especiales conocen materias específicas y se rigen por leyes orgánicas particulares (juzgados de familia, laborales, militares en tiempo de paz, etc.).', 'Ej.: Un conflicto de familia se ve ante un Juzgado de Familia (tribunal especial); en cambio, un caso civil patrimonial se ventila en un Juzgado de Letras civil (tribunal ordinario).', 'Art. 5 COT (integrantes del Poder Judicial ordinario y enumeración de tribunales especiales)', '', '', '["Debate actual: la proliferación de tribunales especiales podría afectar la unidad jurisdiccional. Algunos critican la “especialización excesiva” (familia, laboral, etc.) que fragmenta criterios jurisprudenciales", "Otros defienden que la especialización mejora la eficiencia y conocimientos técnicos. La tensión se refleja en discusiones sobre si ciertas materias (p.ej. corrupción, medio ambiente) deben radicarse en tribunales especializados o seguir bajo los ordinarios con capacitación específica."]'),
('DP-010', 'Recusación e Implicancia', 'Derecho Procesal', 'Disposiciones Orgánicas (Tribunales)', 'Mecanismos para asegurar la imparcialidad del juez. La implicancia opera de pleno derecho ante causales objetivas tasadas (parentesco cercano con una parte, interés en el pleito, etc.), obligando al juez a abstenerse. La recusación es solicitada por una parte cuando concurre alguna causal legal de desconfianza en la imparcialidad del juez (ej. enemistad grave, amistad íntima, interés indirecto) y no se ha abstenido voluntariamente.', 'Ej.: En un juicio donde el juez es hermano del demandante, existe causal de implicancia (parentesco de segundo grado) que lo inhabilita automáticamente (Art. 196 COT); si el juez no se aparta, la parte demandada puede deducir recusación para apartarlo.', 'Arts. 195-200 COT (listas de causales de implicancia y recusación, p. ej. parentesco, amistad/enemistad manifiesta, haber sido abogado en el caso, etc.)', 'CS, 30.07.2018 (Rol 12358-2018): Rechazó recusación contra ministro de Corte Suprema por “sentimientos negativos” del recurrente, al no configurar causal legal de implicancia ni probarse infracción a la imparcialidad', '', '["Jurisprudencia exige pruebas concretas de parcialidad: ha descartado meras sospechas o diferencias de criterio como fundamento de recusación. Se discute si debe ampliarse el catálogo de causales (por ej., perspectiva de género en caso de jueces con expresiones prejuiciosas) o mantener un elenco estricto para evitar recusaciones dilatorias."]'),
('DP-011', 'Demanda', 'Derecho Procesal', 'Juicio Ordinario de Mayor Cuantía', 'Acto procesal inicial por el cual el demandante ejercita su pretensión ante el tribunal competente, dando inicio formal al litigio. Debe cumplir requisitos estrictos: designación del tribunal, individualización de las partes y sus domicilios, exposición clara de los hechos y fundamentos de derecho, y peticiones concretas sometidas a fallo.', 'Ej.: En un juicio de cobro de $100 millones, el acreedor presenta una demanda escrita que identifica al deudor, narra el contrato impago, fundamenta en el Código Civil el incumplimiento y solicita condena de pago más intereses (cumpliendo las exigencias del Art. 254 CPC).', 'Art. 254 CPC (requisitos de la demanda: tribunal, partes, hechos, fundamentos de derecho, petitorio)', 'Corte Suprema, 08.10.2024 (Rol 20.625-2024, Conadecus c. Santander): Confirmó la inadmisibilidad de una demanda colectiva por no contener una exposición clara de los hechos y fundamentos de derecho, reiterando la exigencia del Art. 254 CPC.', '', '["Visiones contrapuestas: una postura formalista exige el estricto cumplimiento de los requisitos (so pena de inadmisibilidad inmediata de la demanda), mientras otra más pro actione propugna interpretar con flexibilidad la suficiencia de la narración fáctica, privilegiando the derecho a la tutela judicial efectiva", "La jurisprudencia reciente oscila: ha declarado inadmisibles libelos imprecisos en demandas colectivas, pero admite subsanaciones menores para evitar sacrificar fondo por la forma."]'),
('DP-012', 'Contestación de la Demanda', 'Derecho Procesal', 'Juicio Ordinario de Mayor Cuantía', 'Escrito mediante el cual el demandado responde a la demanda, aceptando o negando los hechos alegados y formulando sus defensas. Debe contener la individualización del tribunal y partes, las excepciones dilatorias si las hubiere, la contestación de fondo con una exposición precisa de los hechos que se admiten o controvierten y los fundamentos jurídicos de su defensa, pudiendo incluir además demandas reconvencionales.', 'Ej.: En un juicio por incumplimiento contractual, el demandado contesta negando haber incumplido, ofreciendo su propia versión de los hechos (p. ej., alega caso fortuito) y planteando la excepción de falta de legitimación activa, todo dentro del plazo legal de 15 días desde la notificación.', 'Art. 309 CPC (contenido de la contestación: requisitos similares a la demanda, indicando tribunal, partes, aceptación o negación de hechos, defensas de fondo)', '', '', '["Cuestión debatida: si el demandado no contestó (rebeldía), ¿puede el juez tener por confesados los hechos? En Chile rige que la rebeldía no importa aceptación tácita de la demanda, debiendo igualmente el actor probar sus dichos (a diferencia de otros sistemas). Jurisprudencia uniforme: la incomparecencia no exime al demandante de acreditar sus hechos constitutivos, aunque se le facilite la prueba al no haber controversia explícita ."]'),
('DP-013', 'Conciliación', 'Derecho Procesal', 'Juicio Ordinario de Mayor Cuantía', 'Actuación procesal en la fase inicial del juicio ordinario en que el juez procura que las partes logren un avenimiento. Ocurre normalmente tras la etapa de discusión (demanda y contestación). El juez de oficio cita a una audiencia de conciliación y, obrando como amigable componedor, propone fórmulas de arreglo. Si no se logra acuerdo total o parcial, se deja constancia y continúa el juicio.', 'Ej.: En un juicio ordinario sobre indemnización de perjuicios, el juez convoca a las partes a una audiencia de conciliación. Propone que el demandado pague la mitad de lo pedido en un plazo, pero si las partes no aceptan, se certifica el fracaso de la conciliación y se prosigue a fijar los puntos de prueba.', 'Arts. 262-264 CPC (obligatoriedad de citar a conciliación; papel del juez como componedor; acta de avenimiento si hay acuerdo)', '', '', '["Punto crítico: tradicionalmente se discutía si la falta de realización de la audiencia de conciliación era nulidad procesal. La Corte Suprema ha resuelto que la omisión de intentar la conciliación no genera nulidad de oficio, salvo que se acredite perjuicio, pues su finalidad es fomentar acuerdos pero no es requisito de validez del fallo", "Asimismo, se advierte tensión entre el rol activo del juez en conciliar y su imparcialidad: un sector doctrinal estima que no debe presionar a las partes a transigir, para no prejuzgar, mientras otro defiende su deber de promover acuerdos para descongestionar el sistema ."]'),
('DP-014', 'Periodo Probatorio', 'Derecho Procesal', 'Juicio Ordinario de Mayor Cuantía', 'Etapa del juicio, abierta mediante resolución “autos a prueba”, en la que las partes rinden la prueba de los hechos controvertidos fijados por el tribunal. El término probatorio ordinario es común para ambas partes y dura 20 días hábiles cuando la prueba debe rendirse dentro de la jurisdicción, con posibles ampliaciones si se requiere practicar diligencias fuera del territorio o en el extranjero.', 'Ej.: En un juicio ordinario, fijados como puntos de prueba el incumplimiento del contrato y sus daños, las partes disponen de 20 días para presentar testigos, peritajes y documentos pertinentes; si se requieren testigos que residen lejos, el tribunal concede 30 días adicionales por la distancia (tabla de emplazamiento).', 'Arts. 328-329 CPC (duración del término probatorio ordinario y aumento por distancia)', '', '', '["Controversia doctrinal sobre el rol del juez en la etapa probatoria: el sistema chileno se adscribe a la aportación de parte, donde el tribunal es relativamente pasivo y solo valora lo presentado según la sana crítica. Sin embargo, existe debate si debiera otorgarse al juez mayores facultades probatorias de oficio (medidas para mejor resolver) para descubrir la verdad material", "La jurisprudencia, especialmente en sede civil, es restrictiva en admitir prueba ex officio, lo que algunos critican por supeditar la justicia a la habilidad o recursos de las partes."]'),
('DP-015', 'Sentencia', 'Derecho Procesal', 'Juicio Ordinario de Mayor Cuantía', 'Decisión judicial que pone fin al juicio, resolviendo las pretensiones planteadas. La sentencia definitiva debe contener, según el Art. 170 CPC: la designación del tribunal y partes, consideraciones de hecho y de derecho que fundan el fallo, y la parte dispositiva que acoge o rechaza las peticiones. Se exige que sea fundada, congruente con lo litigado y dictada por juez imparcial.', 'Ej.: En un juicio ordinario sobre incumplimiento contractual, la sentencia definitiva expone los hechos probados (existencia del contrato, incumplimiento del demandado), los fundamentos jurídicos (art. 1545 CC, fuerza obligatoria de contratos) y decide acoger la demanda, condenando al demandado a pagar cierta suma, con costas.', 'Arts. 158 y 170 CPC (definición de sentencia definitiva y requisitos formales de toda sentencia: motivaciones y parte resolutiva)', 'Corte Suprema, 21.01.2019, Rol 40166-2017: Invalidó de oficio una sentencia de la CA de Talca por falta de fundamentación, reiterando que la ausencia de consideraciones de hecho o derecho esenciales infringe el Art. 170 CPC y constituye causal de casación en la forma.', '', '["Se plantea el dilema entre exigencia de motivación vs. brevedad: la jurisprudencia ha anulado fallos por motivación aparente o insuficiente, enfatizando el derecho a una sentencia razonada (debido proceso)", "Sin embargo, se advierte riesgo de “jurisprudencia de mérito” si la Corte Suprema evalúa excesivamente la fundamentación, invadiendo competencias del fondo. La discusión se refleja en cómo distinguir entre falta de consideraciones (vicio formal) y mera divergencia en la valoración probatoria (no casable en la forma)."]'),
('DP-016', 'Título Ejecutivo', 'Derecho Procesal', 'Juicios Ejecutivos', 'Documento al cual la ley confiere mérito suficiente para demandar coactivamente una obligación en sede ejecutiva, sin necesidad de juicio declarativo previo. Debe contener una obligación clara, actualmente exigible y liquidable. Ejemplos típicos: una sentencia firme condenatoria, un pagaré o cheque protestado, una escritura pública reconociendo deuda, etc., enumerados en el Art. 434 CPC.', 'Ej.: Un pagaré vencido y debidamente protestado, firmado ante notario, es un título ejecutivo contra el deudor por el capital e intereses allí consignados.', 'Art. 434 CPC (enumeración de títulos con fuerza ejecutiva: sentencias firmes, instrumentos públicos, instrumentos privados reconocidos ante juez, cheques, pagarés con requisitos, etc.)', 'Corte Suprema, 14.01.2026 (Rol 13.345-2025): Declaró que un pagaré firmado bajo condición suspensiva carece de mérito ejecutivo mientras la condición no se cumpla, reiterando que solo obligaciones actualmente exigibles pueden ejecutarse.', '', '["Debate jurisprudencial sobre títulos incompletos o alterados: por ej., pagarés con espacios en blanco llenados sin autorización han sido negados como ejecutivos por la Corte (falta de exigibilidad clara)", "También se discute la validez ejecutiva de contratos con cláusulas aceleratorias automáticas: tendencia judicial a aceptarlos como ejecutivos siempre que la cláusula esté pactada expresamente, mientras la doctrina advierte riesgo de extender la vía ejecutiva a supuestos no previstos estrictamente en la ley."]'),
('DP-017', 'Mandamiento de Ejecución y Embargo', 'Derecho Procesal', 'Juicios Ejecutivos', 'Resolución inicial que despacha la ejecución forzada. Contiene la orden al receptor judicial de requerir de pago al deudor por la suma demandada y, no pagando, embargar bienes suficientes para responder. Su notificación personal al ejecutado es requisito esencial. Marca el comienzo del procedimiento de apremio (embargos, realización de bienes).', 'Ej.: Admitida a trámite la demanda ejecutiva fundada en un pagaré, el tribunal emite mandamiento ordenando al receptor: “Requíérase de pago al deudor X por $10 millones y cúmplase embargo sobre sus bienes suficientes si no paga”. El receptor concurre al domicilio del deudor, lo notifica y embarga bienes (ej. un vehículo) ante la falta de pago inmediato.', 'Arts. 442-443 CPC (contenido del mandamiento: requerimiento de pago personal y embargo en caso de no pago)', '', '', '["Un tema práctico es el cumplimiento efectivo de la notificación personal: la jurisprudencia exige agotar diligencias para notificar personalmente el mandamiento, ya que de ello depende válidamente la traba de embargo y el curso de la ejecución. Se discute si la notificación por cédula del mandamiento (permitida tras intento fallido personal) vulnera garantías del deudor; la postura dominante la admite, siempre que se acrediten esfuerzos razonables de notificación personal previos, conciliando eficacia del cobro y debido proceso."]'),
('DP-018', 'Excepciones del Juicio Ejecutivo', 'Derecho Procesal', 'Juicios Ejecutivos', 'Defensas específicas y taxativas que el ejecutado puede oponer dentro del breve plazo legal (4 días) para paralizar o invalidar la ejecución. Están enumeradas en el Art. 464 CPC e incluyen, entre otras: incompetencia del tribunal, incapacidad del demandante, litispendencia, ineptitud del libelo, falsedad o falta de requisitos del título, pago o extinción de la obligación, prescripción, cosa juzgada, etc.. Solo estas excepciones pueden alegarse en sede ejecutiva.', 'Ej.: Frente a una ejecución hipotecaria, el deudor puede oponer la excepción de pago (numeral 9 del Art. 464 CPC) acreditando que ya canceló la deuda, o la excepción de prescripción de la acción ejecutiva (numeral 17) si ha transcurrido el plazo legal, con lo cual busca que se termine el juicio ejecutivo..', 'Art. 464 CPC (numerales 1° al 18°, listado completo de excepciones admisibles en juicio ejecutivo)', '', '', '["La jurisprudencia es estricta en la taxatividad: no admite defensas fuera del catálogo del Art. 464. Por ej., intentos de oponer “abuso de derecho” o “lesión enorme” como excepción han sido rechazados por no figurar en la lista legal. Crítica doctrinal: el sistema puede ser excesivamente rígido, impidiendo alegar situaciones de injusticia no previstas expresamente. Sin embargo, los tribunales señalan que el ejecutado conserva la vía ordinaria (juicio de conocimiento posterior) para discutir aspectos no incluidos en las excepciones ejecutivas, salvaguardando el debido proceso sin desnaturalizar la ejecución."]'),
('DP-019', 'Remate', 'Derecho Procesal', 'Juicios Ejecutivos', 'Acto de subasta pública de los bienes embargados al ejecutado, ordenado por sentencia de remate o mandamiento firme, para convertirlos en dinero y pagar al acreedor con el producto. Debe realizarse con publicidad y bajo las bases fijadas por el tribunal (mínimo, forma de pago, cauciones). Se anuncia mediante avisos en diarios locales al menos por 4 veces antes de la fecha de subasta.', 'Ej.: En una ejecución hipotecaria, una vez dictada la sentencia de remate, se publica en un diario de la comuna un aviso indicando que el inmueble del deudor se subastará tal día en el juzgado, con postura mínima de $50 millones. El día del remate, se presentan postores, se adjudica al mejor oferente y este debe consignar el precio según lo establecido.', 'Arts. 488-495 CPC (procedimiento del remate: publicaciones, posturas, pago del precio, acta de remate, sanciones por incumplimiento del adjudicatario)', '', '', '["Problemáticas frecuentes: remates desiertos (sin postores) obligan a rebajar mínimum o a prenda pretoria en favor del acreedor, lo cual se ha criticado como posible enriquecimiento del ejecutante. La jurisprudencia ha abordado también nulidades de remate por vicios en la publicidad o colusión entre postores: ha dejado sin efecto subastas cuando no se cumplió con los avisos legales o hubo maquinaciones para bajar el precio, ponderando el equilibrio entre seguridad jurídica del remate y protección del deudor contra liquidaciones irrisorias."]'),
('DP-020', 'Tercerías', 'Derecho Procesal', 'Juicios Ejecutivos', 'Intervenciones de terceros en un juicio ejecutivo para reclamar derechos propios sobre los bienes embargados o el producto de ellos. Solo se admiten en cuatro casos: 1) tercería de dominio (tercero alega ser dueño de los bienes embargados); 2) de posesión (alega tenencia legítima); 3) de prelación (tercero acreedor con crédito privilegiado que pide ser pagado antes); 4) de pago (tercero solicita se le pague a él con lo obtenido).', 'Ej.: A un ejecutado se le embarga un vehículo, pero un tercero presenta una tercería de dominio afirmando que el auto le pertenece (p. ej., por compraventa anterior). El tercerista deberá probar su dominio en un juicio incidental; mientras tanto, el remate del bien embargado podría suspenderse o el dinero quedar consignado en custodia hasta resolver la tercería.', 'Arts. 518-525 CPC (regulan las tercerías: procedencia, tramitación separada de la de dominio por juicio ordinario breve, tercería de prelación/pago como incidentes, efectos sobre el procedimiento de apremio)', '', '', '["Un punto de fricción es el uso malicioso de tercerías para entorpecer la ejecución: la jurisprudencia exige seriedad en la prueba del derecho invocado por el tercerista. Por eso, el Art. 522 CPC impide suspender la ejecución salvo que la tercería de dominio se apoye en título público anterior a la demanda. Se discute si la tercería de dominio debería resolverse más ágilmente (vvia incidental) para evitar dilaciones, pero ello podría comprometer el debido proceso del tercerista; la solución de equilibrio ha sido mantener el juicio ordinario para dominio, pero permitiendo al acreedor pedir caución al tercerista para no frenar injustificadamente el remate."]'),
('DP-021', 'Recurso de Apelación', 'Derecho Procesal', 'Recursos Procesales', 'Medio de impugnación ordinario que permite a la parte agraviada por una resolución judicial obtener su revisión por el tribunal superior. El fin de la apelación es que el superior corrija con arreglo a derecho la resolución del inferior, pudiendo confirmar, revocar o modificar lo decidido. En materia civil procede contra sentencias definitivas de primera instancia y ciertas interlocutorias, según reglas legales.', 'Ej.: En un juicio civil, la sentencia del Juzgado de Letras que rechaza la demanda puede ser apelada por el demandante ante la Corte de Apelaciones respectiva, la cual reexaminará el caso y dictará su propio fallo confirmatorio o revocatorio del de primera instancia.', 'Arts. 186-193 CPC (objeto, plazo y efectos de la apelación; apelaciones en ambos efectos o solo devolutivo según el caso)', '', '', '["Tensión práctica: el derecho a la doble instancia vs. la necesidad de celeridad. En Chile, la apelación en materia civil generalmente se concede en ambos efectos (suspensivo y devolutivo), lo que prolonga la ejecución del fallo. Se ha propuesto limitar apelaciones o conceder solo efecto devolutivo en ciertos casos para acelerar procesos, pero se advierte que podría menoscabar garantías. La jurisprudencia ha equilibrado admitiendo adhesión a la apelación y consolidando el estándar de la “no reformatio in peius” (el apelante único no puede quedar en peor situación tras la apelación), protegiendo el derecho de defensa en la segunda instancia."]'),
('DP-022', 'Recurso de Casación en la Forma', 'Derecho Procesal', 'Recursos Procesales', 'Recurso extraordinario que busca invalidar una sentencia viciada por errores procedimentales graves. Se funda en causales taxativas (Art. 768 CPC), como: tribunal incompetente, ultra petita (fallo otorga más de lo pedido), sentencia incongruente o falta de fundamentación, entre otras. Apunta a anular el fallo por infracción a las formas sustanciales del procedimiento.', 'Ej.: Tras una sentencia de segunda instancia que omitió pronunciarse sobre una excepción sustancial alegada (omisión que vulnera el debido proceso), la parte afectada interpone casación en la forma ante la Corte Suprema invocando la causal del N°5 del Art. 768 CPC (omisión de consideraciones), solicitando la nulidad del fallo y la emisión de uno nuevo correctamente motivado.', 'Arts. 767-768 CPC (procedencia de casación en sentencias inapelables; causales formales específicas)', 'Corte Suprema, 21.01.2019, Rol 40166-2017: Acogió de oficio casación en la forma contra una sentencia de la CA Talca, por faltar las consideraciones de hecho y derecho (causal del Art. 768 N°5 CPC), invalidando el fallo y ordenando sentencia nueva.', '', '["Se discute si la casación en la forma debe interpretarse restrictivamente por su naturaleza extraordinaria o si la Corte Suprema ha ampliado su alcance indebidamente. Algunos académicos critican un “formalismo excesivo” cuando se acoge casación por vicios menores sin trascendencia real en el resultado", "No obstante, la Corte ha reiterado que las formalidades esenciales son garantía de un debido proceso, prevaleciendo la nulidad cuando se verifica una causal, aunque existan fallos (minoría) en que la CS ha declarado el principio de conservación del acto procesal, desestimando casaciones formales por aplicación de la teoría del perjuicio (vgr., CAS 37.233-2019)."]'),
('DP-023', 'Recurso de Casación en el Fondo', 'Derecho Procesal', 'Recursos Procesales', 'Recurso extraordinario ante la Corte Suprema, procedente contra sentencias definitivas o interlocutorias inapelables de tribunales superiores, cuando en ellas se ha infringido la ley sustantiva y dicha infracción ha influido substancialmente en lo dispositivo del fallo. Busca la correcta aplicación del derecho objetivo, más que la revisión de los hechos del caso.', 'Ej.: Una Corte de Apelaciones confirma una sentencia pero aplica erróneamente una norma de prescripción, calculando mal el plazo. La parte perjudicada interpone casación en the fondo por infracción de ley (artículo de prescripción del CC) ante la Corte Suprema, para que anule lo resuelto y dicte sentencia conforme a la norma bien interpretada.', 'Arts. 766-772 CPC (requisitos y causales de casación de fondo: quebrantamiento de ley sustancial decisiva)', 'CS, 28.02.2020, Rol 29.411-2019: Acogió casación en el fondo y anuló sentencia laboral que había aplicado incorrectamente la norma de indemnización por años de servicio, corrigiendo el cálculo a favor del trabajador', '', '["Existe fricción entre el rol unificador de la Corte Suprema y el respeto a la soberanía del tribunal de instancia en la valoración de la prueba. La casación en el fondo no puede revisar hechos, solo derecho, pero en ocasiones la línea se difumina: críticos acusan a la Corte de revalorar implícitamente prueba so pretexto de error de derecho. A su vez, se plantea instaurar un recurso de unificación de jurisprudencia más amplio (como existe en laboral) para resolver discrepancias sin necesidad de invocar errores in procedendo o in iudicando estrictos."]'),
('DP-024', 'Recurso de Queja', 'Derecho Procesal', 'Recursos Procesales', 'Recurso de carácter disciplinario que se interpone ante una Corte superior (Corte de Apelaciones o Suprema, según el caso) para corregir faltas o abusos graves cometidos por un juez en la dictación de una resolución no susceptible de recursos ordinarios ni extraordinarios. Su objetivo es tutelar la recta administración de justicia sancionando al juez infractor y enmendando el perjuicio causado por su resolución.', 'Ej.: Una Corte de Apelaciones dicta una sentencia definitiva inapelable en un recurso de protección con manifiesto error jurídico y con posible arbitrariedad. La parte afectada presenta recurso de queja ante la Corte Suprema acusando falta grave en la decisión, solicitando se deje sin efecto el fallo y se sancione disciplinariamente a los ministros que incurrieron en el abuso.', 'Art. 545 COT (procede queja por falta o abuso grave en sentencia interlocutoria o definitiva inapelable)', 'CS, 24.11.2025, Rol 250.587-2023: Rechazó queja contra una Corte que declaró prescrita una acción penal, enfatizando que una mera discrepancia en la interpretación de la ley no configura por sí sola falta o abuso grave que dé lugar a la queja.', '', '["La Corte Suprema ha limitado el alcance de la queja: ha reiterado que no es una “tercera instancia” para revisar el fondo de los asuntos, sino un mecanismo estrictamente disciplinario. Solo procede ante actuaciones judiciales aberrantes sin remedio recursal. Se debate si su uso actual desborda lo disciplinario (corrigiendo errores jurídicos bajo la etiqueta de abuso grave) o si, por el contrario, la CS ha sido correcta al restringirlo, como en fallos donde declara improcedente la queja cuando existen recursos legales disponibles o la cuestión es de mera discrepancia jurídica."]'),
('DP-025', 'Recurso de Reposición', 'Derecho Procesal', 'Recursos Procesales', 'Medio de impugnación horizontal, por el cual una parte solicita al mismo tribunal que dictó una resolución de trámite (autos, decretos o ciertas interlocutorias) que la reconsidere o enmiende, por estimarla errónea o perjudicial. Se interpone dentro de un breve plazo (generalmente 3 días) desde la notificación de la resolución y puede ser con o sin “apelación en subsidio”.', 'Ej.: El juez dicta una resolución que rechaza por extemporáneo un escrito de prueba; la parte afectada interpone reposición dentro de 3 días argumentando que presentó el escrito en plazo hábil, pidiendo al mismo juez que revoque su decisión. Si el juez rechaza la reposición, queda expedita la apelación subsidiaria si se interpuso.', 'Art. 81 CPC (procedencia de reposición contra autos y decretos dentro de tercero día); Art. 362 Código Procesal Penal (reposiciones en procedimiento penal)', '', '', '["Se discute la efectividad real de la reposición: muchos la consideran de escasa incidencia ya que el mismo juez raramente cambia su criterio, sirviendo principalmente para agotar instancia o dejar constancia para una eventual apelación. Sin embargo, en práctica ha permitido corregir errores evidentes (p. ej., cálculos aritméticos, citas legales equivocadas) sin necesidad de acudir al superior", "Algunos tribunales resuelven de plano las reposiciones, otros las oyen “con audiencia” de la contraparte; la falta de uniformidad ha generado debate sobre si la reposición debe otorgar siempre traslado para mayor bilateralidad, o si ello la haría demasiado lenta contraviniendo su naturaleza expedita."]'),
('DP-026', 'Principio Acusatorio', 'Derecho Procesal', 'Procedimiento Penal (Reforma Procesal Penal)', 'Eje del nuevo sistema penal chileno que separa las funciones de investigar, acusar y juzgar. La persecución penal la dirige en forma exclusiva el Ministerio Público, mientras un juez de garantía imparcial controla la legalidad del procedimiento y otro tribunal (Tribunal de Juicio Oral) resuelve sobre la culpabilidad. Implica oralidad, publicidad, contradicción y que el juez no actúa de oficio en la investigación (a diferencia del antiguo sistema inquisitivo).', 'Ej.: Ante un delito, el fiscal reúne evidencias e imputa cargos, el juez de garantía vela por los derechos del imputado (p. ej., autorizando cautelares si proceden) y finalmente un tribunal oral colegiado decide la condena o absolución en juicio. El juez no investiga por sí mismo, respetando la división acusador/juzgador.', 'Arts. 1, 3 Código Procesal Penal (CPP) (juicio previo ante tribunal imparcial; investigación a cargo exclusivo del MP)', '', '', '["Tensión práctica: si bien el fiscal conduce la investigación, se cuestiona el “desequilibrio” de poderes, pues la defensa depende de lo aportado por el MP. Algunos critican que el principio acusatorio llevó a un juez más pasivo; sin embargo, la jurisprudencia ha perfilado un juez de garantía activo en cautelar derechos fundamentales (anulando actuaciones viciadas o controlando plazos), lo que equilibra el sistema", "El debate persiste en torno a figuras híbridas como el juez de la investigación propuesto en ciertas reformas, que a juicio de detractores reintroduciría elementos inquisitivos, mientras defensores alegan que fortalecería la eficacia investigativa sin menoscabar garantías."]'),
('DP-027', 'Formalización de la Investigación', 'Derecho Procesal', 'Procedimiento Penal (Reforma Procesal Penal)', 'Acto procesal mediante el cual el fiscal comunica al imputado, en audiencia ante el juez de garantía, que se desarrolla una investigación penal en su contra por hechos determinados. A partir de la formalización, el imputado adquiere derechos plenos de defensa (acceso a la carpeta investigativa, solicitar diligencias) y el proceso penal entra en la etapa formal. No es una acusación, sino un hito intermedio que posibilita cautelares y fija el punto de inicio del procedimiento penal formal.', 'Ej.: En un caso de robo, el fiscal solicita audiencia de formalización. En dicha audiencia, le indica al imputado “se le investiga por robo ocurrido el 5 de marzo en…”, ante el juez. Desde entonces, el imputado puede pedir pruebas, y el fiscal ya puede solicitar medidas cautelares (p. ej., prisión preventiva).', 'Art. 229 CPP (define la formalización como la comunicación al imputado, ante juez, de la existencia de una investigación en su contra)', '', '', '["La formalización ha generado debate respecto a su oportunidad: fiscalía suele demorarse hasta reunir antecedentes suficientes, lo que para la defensa puede implicar investigaciones “secretas” prolongadas. El Tribunal Constitucional ha señalado que la formalización marca el inicio del plazo de investigación y del control judicial, garantizando derechos del imputado. También se discute su no-recurribilidad: al no ser resolución, no admite recursos, lo que ha sido criticado por limitar el control; no obstante, se puede reclamar ante superiores del MP por abuso en formalizaciones arbitrarias, correctivo más bien interno."]'),
('DP-028', 'Medidas Cautelares Personales', 'Derecho Procesal', 'Procedimiento Penal (Reforma Procesal Penal)', 'Restricciones impuestas al imputado durante la investigación para asegurar fines del proceso (comparecencia, seguridad de la sociedad o de la víctima). Van desde la prisión preventiva (privación de libertad) hasta medidas menos gravosas: arresto domiciliario, prohibición de acercarse a la víctima, firma periódica, arraigo (prohibición de salir del país), entre otras. La prisión preventiva procede solo si las demás resultan insuficientes y existieren antecedentes de peligro de fuga o de peligro para la seguridad.', 'Ej.: A un imputado por robo con intimidación, sin antecedentes penales, el juez de garantía le decreta arresto domiciliario nocturno y arraigo nacional en lugar de prisión preventiva, al considerar que con esas medidas se asegura su sujeción al procedimiento y la seguridad de la víctima.', 'Arts. 140-146 CPP (presupuestos de la prisión preventiva: indicios de delito y necesidad por peligro de fuga o para la sociedad); Art. 155 CPP (medidas cautelares menos gravosas)', '', '', '["La aplicación de la prisión preventiva ha sido foco de intensa crítica: por un lado, jueces y fiscales la emplean extensamente (se habla de “prisión preventiva como pena anticipada”), suscitando reproches de vulneración de la presunción de inocencia. La Corte Suprema ha reiterado su carácter excepcional y exigido fundamentar en concreto la necesidad de la medida, revocando prisiones preventivas arbitrarias vía recurso de amparo", "Por otro lado, clamor social ante delitos violentos lleva a presiones para endurecer su uso. El debate se centra en equilibrar seguridad pública y derecho a la libertad: reformas recientes han acotado plazos máximos de investigación con detenido, para impedir prolongaciones indefinidas de cautelares personales."]'),
('DP-029', 'Audiencia de Preparación de Juicio Oral', 'Derecho Procesal', 'Procedimiento Penal (Reforma Procesal Penal)', 'También llamada etapa intermedia, es la audiencia ante el juez de garantía en que se depura el caso que irá a juicio oral. Tras la formalización y cierre de la investigación, el fiscal presenta la acusación y en esta audiencia se discuten las pruebas que cada parte pretende llevar al juicio. El juez resuelve sobre su admisibilidad, excluyendo pruebas ilícitas o impertinentes, y dicta el auto de apertura de juicio oral con los hechos precisos de acusación y la nómina de prueba admitida.', 'Ej.: En un caso de lesiones graves, en la audiencia preparatoria el defensor se opone a la incorporación de cierta declaración por haber sido obtenida sin abogado (prueba ilícita). El juez de garantía acoge la objeción y excluye esa declaración. Luego de debatir todas las pruebas, el juez dicta auto de apertura, estableciendo qué pruebas sí se rendirán ante el tribunal oral.', 'Arts. 259-274 CPP (acusación y preparación del juicio oral: intercambio de escritos acusatorios, audiencia para acuerdos probatorios, admisibilidad de prueba y auto de apertura)', '', '', '["Esta fase equilibra garantías y eficiencia: permite filtrar prueba ilegal o irrelevante antes del juicio. Sin embargo, se debate si los jueces de garantía a veces aplican un estándar demasiado laxo o estricto al excluir pruebas. Por ej., jurisprudencia diversa en criterios de exclusión de testigos no individualizados en acusación ha generado incertidumbre. También se analiza la conciliación en delitos no graves durante esta etapa: algunos la fomentan para descongestionar (ej. acuerdo reparatorio), mientras otros advierten que puede trivializar la acción penal. La tendencia apunta a fortalecer esta audiencia como espacio clave de preparación, enfatizando principios de descubrimiento probatorio recíproco y lealtad procesal."]'),
('DP-030', 'Juicio Oral', 'Derecho Procesal', 'Procedimiento Penal (Reforma Procesal Penal)', 'Fase culminante del proceso penal, donde un tribunal colegiado (3 jueces profesionales) conoce públicamente, en forma oral y contradictoria, la prueba sobre la acusación formulada, para dictar veredicto y sentencia. Rige la inmediación (los jueces deben presenciar directamente la rendición de pruebas) y la continuidad (audiencia ininterrumpida hasta conclusión). El juicio oral es público, salvo excepciones para proteger bienes jurídicos sensibles.', 'Ej.: En un juicio oral por robo, comparecen los testigos de cargo y descargo, se presentan peritajes (todo en audiencia oral). Los jueces escuchan los alegatos finales de fiscal y defensa y luego deliberan para emitir veredicto absolutorio o condenatorio, y en caso de condena dictan la sentencia con la pena correspondiente.', 'Arts. 280-303 CPP (principios del juicio oral: publicidad, oralidad, inmediación, concentración; desarrollo: orden de prueba, interrogatorios, alegatos finales)', '', '', '["Un desafío es la valoración de la prueba conforme a la sana crítica: al no haber actas escritas integrales, la convicción de los jueces se forma por lo percibido directamente, lo que dificulta su revisión en recursos (solo vía nulidad por infracción de garantías). Esto ha generado discusiones sobre la necesidad de grabación audiovisual completa y su alcance en el recurso de nulidad. Asimismo, se tensiona la celeridad con el derecho de defensa: juicios maratónicos pueden afectar la concentración de partes y jueces; la jurisprudencia ha anulado juicios por violar la continuidad (suspensiones excesivas), reforzando que la fragmentación del juicio atenta contra la inmediación. En suma, el juicio oral realiza plenamente el contradictorio, pero impone altas exigencias logísticas y personales al sistema penal."]'),
('DP-031', 'Jurisdicción', 'Derecho Procesal', 'Orgánico', 'Poder-deber que tienen los tribunales para conocer y resolver, por medio del proceso y con efecto de cosa juzgada, los conflictos de intereses de relevancia jurídica.', 'La Corte Suprema resolviendo un recurso extraordinario de revisión o casación en el fondo con autoridad soberana plena,.', 'Colombo Campbell', '', '', '["Es indelegable e improrrogable.", "Su falta genera la inexistencia procesal del acto."]'),
('DP-032', 'Competencia', 'Derecho Procesal', 'Orgánico', 'Esfera, grado o medida fijada por el legislador para que la jurisdicción se ejerza por cada tribunal específico.', 'Un juez de letras conociendo de un asunto civil de mayor cuantía en su territorio jurisdiccional.', 'Art. 108 COT', '', '', '["Puede delegarse parcialmente mediante exhortos.", "Su infracción o falta genera la nulidad procesal."]'),
('DP-033', 'Prórroga de la Competencia', 'Derecho Procesal', 'Orgánico', 'Acuerdo expreso o tácito de las partes para otorgar competencia a un tribunal que naturalmente no es el competente para conocer del asunto.', 'El demandado contesta una demanda civil ante un tribunal de distinto territorio sin alegar la incompetencia.', 'Art. 187 CPC', '', '', '["Procede solo en asuntos civiles contenciosos de primera instancia.", "Permite alterar únicamente el factor territorio, nunca la materia o fuero."]'),
('DP-034', 'Regla de Radicación', 'Derecho Procesal', 'Orgánico', 'Principio normativo que establece que, radicado con arreglo a la ley el conocimiento de un negocio ante tribunal competente, no se alterará esta competencia por causa sobreviniente.', 'Un demandado cambia de domicilio a otra ciudad durante el juicio, pero el tribunal original sigue siendo el competente para fallar,.', 'Art. 109 COT', '', '', '["Requiere la intervención formal de un tribunal competente mediante notificación válida.", "Genera el estado de litis pendencia y fija irremediablemente la competencia."]'),
('DP-035', 'Equivalentes Jurisdiccionales', 'Derecho Procesal', 'Teoría General', 'Formas de solución de conflictos distintas del proceso jurisdiccional que producen un efecto vinculante asimilable a la cosa juzgada,.', 'La celebración de un contrato de transacción o un avenimiento aprobado por el juez,.', 'Doctrina Procesal (Carnelutti)', '', '', '["Constituyen actos de autocomposición que ponen término anticipado al litigio.", "Producen eficacia de cosa juzgada material al igual que una sentencia definitiva."]'),
('DP-036', 'Proceso', 'Derecho Procesal', 'Teoría General', 'Medio idóneo para dirimir imparcialmente, por acto de juicio de autoridad, un conflicto de relevancia jurídica mediante una resolución que eventualmente puede adquirir la fuerza de la cosa juzgada,.', 'La totalidad de la secuela de actos desde la llegada hasta el cumplimiento de la sentencia para el cobro de una deuda.', 'Doctrina Procesal', '', '', '["Es un concepto abstracto y único enfocado en la finalidad de resolver la controversia.", "Su culminación lógica y esperada es la dictación de una sentencia firme."]'),
('DP-037', 'Procedimiento', 'Derecho Procesal', 'Teoría General', 'Conjunto de formalidades, trámites, ritos externos o actuaciones a través de las cuales se desarrolla materialmente el proceso judicial,.', 'El juicio ordinario que establece etapas estrictas de discusión, prueba y fallo.', 'Doctrina Procesal', '', '', '["Constituye el aspecto exterior, formal y dinámico del fenómeno procesal.", "Existen múltiples procedimientos (ordinario, sumario, ejecutivo) para sustanciar procesos de diversa naturaleza."]'),
('DP-038', 'Juicio', 'Derecho Procesal', 'Teoría General', 'Controversia jurídica y actual producida entre dos o más personas sobre un derecho y que se somete a la decisión jurisdiccional de un tribunal,.', 'El litigio puntual entre arrendador y arrendatario por el no pago de las rentas,.', 'Casarino Viterbo', '', '', '["Sus elementos constitutivos son la contienda, las partes y el tribunal llamado a resolverla.", "Suele utilizarse doctrinariamente como el procedimiento específico a través del cual se desarrolla el proceso."]'),
('DP-039', 'Partes', 'Derecho Procesal', 'Sujetos Procesales', 'Aquellas personas que sostienen formalmente ante un tribunal una contienda jurídica y actual acerca de sus propios derechos e intereses.', 'El acreedor demandante que exige el pago y el deudor demandado que rechaza la deuda.', 'Doctrina Procesal', '', '', '["Se clasifican fundamentalmente en directas o principales e indirectas o terceros.", "Para intervenir válidamente requieren contar con capacidad procesal."]'),
('DP-040', 'Terceros', 'Derecho Procesal', 'Sujetos Procesales', 'Personas distintas del demandante y del demandado que comparecen al juicio por tener comprometido en él un derecho, sosteniendo peticiones.', 'Un legatario que decide intervenir voluntariamente en el juicio donde los herederos discuten la nulidad del testamento.', 'Doctrina Procesal', '', '', '["Su intervención procedimental se denomina jurídicamente como tercería.", "Se subclasifican en terceros coadyuvantes, independientes y excluyentes."]'),
('DP-041', 'Patrocinio', 'Derecho Procesal', 'Comparecencia en Juicio', 'Contrato por el cual las partes o interesados en un asunto judicial encomiendan a un abogado habilitado la defensa técnica de sus pretensiones ante los tribunales.', 'Un abogado que asume la dirección jurídica de un caso asumiendo la firma y responsabilidad en el primer escrito.', 'Ley Nº 18.120', '', '', '["El profesional asume la responsabilidad civil, criminal y disciplinaria de la defensa.", "Se diferencia del mandato judicial en que este último se restringe a la mera representación procesal."]'),
('DP-042', 'Mandato Judicial', 'Derecho Procesal', 'Comparecencia en Juicio', 'Contrato procesal mediante el cual una persona otorga a otra facultades suficientes para que la represente formal y válidamente ante los tribunales de justicia.', 'Una persona confiere mandato mediante escritura pública a un procurador del número para tramitar su caso civil,.', 'Ley Nº 18.120', '', '', '["Debe recaer obligatoriamente en abogados habilitados, procuradores del número o postulantes de la corporación.", "Su no constitución legal acarrea que el tribunal tenga por no presentado el escrito respectivo."]'),
('DP-043', 'Demanda', 'Derecho Procesal', 'Juicio Ordinario', 'Acto procesal introductivo de instancia por virtud de la cual el actor somete su pretensión al juez, con las formas requeridas por la ley, pidiendo una sentencia favorable en su interés.', 'El escrito principal mediante el cual el actor exige indemnización por incumplimiento de un contrato.', 'Art. 254 CPC / Couture', '', '', '["Es la vía formal y material a través de la cual se ejercita la acción procesal.", "Fija los límites del juicio y el marco sobre el cual deberá recaer la congruencia de la sentencia definitiva."]'),
('DP-044', 'Emplazamiento', 'Derecho Procesal', 'Disposiciones Comunes', 'Notificación de la demanda, a la cual se agrega la orden de que el notificado comparezca al tribunal dentro del término señalado por éste.', 'El receptor notifica la demanda civil al deudor, abriendo el plazo fatal legal para que este conteste.', 'Doctrina Procesal', '', '', '["Se compone de dos elementos copulativos: la notificación legal y el transcurso íntegro del plazo.", "Su omisión o defecto grave configura un vicio esencial que anula la validez de todo el procedimiento."]'),
('DP-045', 'Notificación Personal', 'Derecho Procesal', 'Notificaciones', 'Forma legal de notificación que consiste en entregar directamente a la persona a quien se debe notificar, en forma física, copia íntegra de la resolución y de la solicitud respectiva.', 'El receptor judicial entrega en propias manos del demandado la resolución que admite a tramitación la primera demanda civil,.', 'Art. 40 CPC', '', '', '["Es la regla obligatoria e ineludible para la primera notificación a las partes en toda gestión judicial,.", "Garantiza de forma directo el efectivo conocimiento del acto procesal fundamental."]'),
('DP-046', 'Notificación por el Estado Diario', 'Derecho Procesal', 'Notificaciones', 'Ficción legal en que se entiende válidamente notificada una resolución por el solo hecho de incluirse la noticia de su dictación en una nómina electrónica diaria,.', 'La resolución de mero trámite de traslado se incorpora en el sistema informático del tribunal quedando las partes legalmente informadas.', 'Art. 50 CPC', '', '', '["Constituye la regla generalísima para notificar actos de tramitación normal en el proceso civil.", "La inclusión se realiza en un estado electrónico disponible permanentemente en el portal del Poder Judicial."]'),
('DP-047', 'Plazo Fatal', 'Derecho Procesal', 'Plazos Procesales', 'Espacio de tiempo en que la posibilidad de ejercer un derecho o ejecutar un acto procesal se extingue automáticamente a su vencimiento por el solo ministerio de la ley.', 'El plazo legal de quince días para contestar la demanda ordinaria que precluye automáticamente si no se presenta el escrito a tiempo.', 'Art. 64 CPC', '', '', '["La gran mayoría de los plazos que establece el Código de Procedimiento Civil revisten esta naturaleza perentoria.", "No requieren de declaración judicial ni certificado de rebeldía previo para que opere su pleno efecto preclusivo."]'),
('DP-048', 'Rebeldía', 'Derecho Procesal', 'Plazos Procesales', 'Situación jurídica que se le produce al litigante que deja de evacuar un trámite o de practicar una diligencia en el plazo que señala el tribunal.', 'El demandante no evacúa el trámite de observaciones a la prueba, por lo que el tribunal declara evacuado el trámite en su rebeldía.', 'Art. 78 CPC', '', '', '["Obliga al tribunal, de oficio o a petición de parte, a declarar el trámite por evacuado y dar curso progresivo a la sustanciación.", "Puede ser objeto de rescisión si la parte demuestra fehacientemente haber estado impedida por fuerza mayor."]'),
('DP-049', 'Excepciones Dilatorias', 'Derecho Procesal', 'Juicio Ordinario', 'Defensas procesales que tienen por objeto corregir los vicios de validez procesal al momento de formarse la relación jurídica y corregir el procedimiento.', 'El demandado alega la incompetencia del tribunal o la ineptitud del libelo por falta de claridad en las peticiones de la demanda.', 'Art. 303 CPC', '', '', '["Se tramitan obligatoriamente como un incidente de previo y especial pronunciamiento.", "Buscan sanear y purificar la relación jurídica procesal antes de entrar al debate del fondo."]'),
('DP-050', 'Excepciones Perentorias', 'Derecho Procesal', 'Juicio Ordinario', 'Defensas jurídicas de carácter sustancial que miran directamente al fondo del asunto y tienen por exclusivo objeto enervar, destruir o extinguir la acción deducida.', 'Frente a la demanda de cobro de dinero, el demandado contesta oponiendo el pago efectivo de la deuda o la prescripción.', 'Doctrina Procesal', '', '', '["A diferencia de las dilatorias, no suspenden el proceso, sino que persiguen el rechazo íntegro de la demanda en la sentencia final.", "Suelen coincidir e identificarse directamente con los modos normativos civiles de extinguir las obligaciones."]'),
('DP-051', 'Reconvención', 'Derecho Procesal', 'Juicio Ordinario', 'Demanda procesal nueva que el demandado deduce en contra del demandante original en el propio escrito de contestación de la demanda.', 'En un juicio ordinario por incumplimiento contractual, el demandado contesta y a su vez demanda exigiendo indemnización por mejoras,.', 'Art. 314 CPC', '', '', '["Se tramita conjuntamente y se falla de forma obligatoria en la misma sentencia definitiva de la acción principal.", "Materializa el principio de economía procesal y evita el alto riesgo de dictar sentencias contradictorias."]'),
('DP-052', 'Incidentes', 'Derecho Procesal', 'Disposiciones Comunes', 'Toda cuestión procedimental accesoria a un juicio principal que requiere de un pronunciamiento judicial especial, con o sin audiencia de partes,.', 'Un litigante promueve la nulidad de una notificación defectuosa o solicita el alzamiento judicial de una medida precautoria.', 'Art. 82 CPC', '', '', '["Se pueden subclasificar procesalmente en incidentes ordinarios, especiales, de previo y especial pronunciamiento, conexos o inconexos,.", "Su tramitación comprende una etapa de discusión, prueba y un fallo emitido típicamente en un auto o interlocutoria,."]'),
('DP-053', 'Acumulación de Autos', 'Derecho Procesal', 'Incidentes Especiales', 'Incidente procesal especial que tiene por objeto obtener que el tribunal ordene agrupar materialmente dos o más procesos pendientes y conexos para tramitarlos y fallarlos conjuntamente.', 'Se acumula un juicio declarativo de nulidad de contrato a otro que persigue el cobro coactivo del mismo.', 'Art. 92 CPC', '', '', '["Su finalidad suprema y fundante es mantener la continencia de la causa y evitar el pronunciamiento de sentencias contradictorias.", "Exigen copulativamente que los juicios afectados se encuentren en instancias análogas y sometidos al mismo procedimiento legal."]'),
('DP-054', 'Abandono del Procedimiento', 'Derecho Procesal', 'Incidentes Especiales', 'Sanción procesal que declara el término anticipado del procedimiento por la inactividad de las partes que han cesado en su prosecución durante seis meses.', 'El juicio civil se estanca ocho meses sin que nadie pida prueba, por lo que el demandado solicita al juez que declare extinguido el proceso.', 'Art. 152 CPC', '', '', '["Provoca la pérdida de todo lo obrado en el juicio, castigando la negligencia de los litigantes.", "No extingue directamente la pretensión ni la acción material subyacente, permitiendo al actor entablar una demanda nueva."]'),
('DP-055', 'Desistimiento de la Demanda', 'Derecho Procesal', 'Incidentes Especiales', 'Acto jurídico procesal unilateral, formalizado por el actor, mediante el cual manifiesta su voluntad de renunciar a la pretensión hecha valer, extinguiendo el proceso,.', 'El demandante, percatándose de un error estratégico insalvable, presenta un escrito desistiéndose tras haber notificado al demandado.', 'Art. 148 CPC', '', '', '["Se tramita rigurosamente como un incidente y requiere una resolución jurisdiccional interlocutoria que lo acoja.", "Produce un efecto definitivo extinguiendo la pretensión procesal originando la fuerza de cosa juzgada."]'),
('DP-056', 'Medidas Prejudiciales', 'Derecho Procesal', 'Medidas Cautelares', 'Providencias de naturaleza preparatoria o conservadora que puede o debe decretar el tribunal, antes del inicio formal de un juicio, para hacer posible o facilitar las futuras acciones o defensas.', 'Ej.: Un futuro demandante solicita la exhibición judicial de los libros de contabilidad de la empresa adversaria para fundar precisamente su demanda,.', 'Art. 273 CPC', '', '', '["La doctrina procesal las subclasifica en preparatorias, probatorias y netamente precautorias prejudiciales.", "Buscan garantizar razonablemente que la entrada al futuro litigio sea con los elementos de juicio y pruebas indispensables."]'),
('DP-057', 'Medidas Precautorias', 'Derecho Procesal', 'Medidas Cautelares', 'Providencias dictadas por el juez durante el curso del juicio que están dirigidas a asegurar el resultado práctico y el cumplimiento patrimonial de la acción deducida,.', 'La retención de dineros bancarios del demandado o la prohibición judicial de celebrar actos sobre un inmueble disputado.', 'Art. 290 CPC', '', '', '["Exigen comprobar al menos la presunción grave del derecho que se reclama y requieren caución en ciertos casos.", "Son resoluciones esencialmente provisionales, limitadas a los bienes necesarios y pueden ser sustituidas por garantías suficientes."]'),
('DP-058', 'Resoluciones Judiciales', 'Derecho Procesal', 'Teoría de las Resoluciones', 'Acto jurídico procesal que emana formalmente del tribunal o sus auxiliares, destinado a dar curso progresivo al procedimiento (sustanciar) o a fallar la controversia del juicio.', 'Desde un simple decreto que ordena el "Traslado" de un escrito hasta la extensa sentencia definitiva que condena al deudor,.', 'Art. 158 CPC', '', '', '["El legislador las clasifica jerárquicamente en sentencias definitivas, sentencias interlocutorias, autos y decretos o proveídos.", "Su correcta naturaleza legal determina la procedencia admisible de los recursos procesales y sus efectos de cosa juzgada."]'),
('DP-059', 'Sentencia Definitiva', 'Derecho Procesal', 'Teoría de las Resoluciones', 'Resolución magna que pone fin a la instancia jurisdiccional, resolviendo y zanjando íntegramente la cuestión o asunto que ha sido objeto principal del pleito.', 'El fallo del juez de letras que, al terminar todo el proceso civil, condena al ejecutado al pago del crédito insoluto.', 'Art. 158 CPC', '', '', '["Debe cumplir con formalidades rigurosas que incluyen necesariamente una parte expositiva, considerativa y resolutiva,.", "Es la resolución judicial natural y esperada sobre la cual recae con máxima intensidad el efecto inmutable de la cosa juzgada."]'),
('DP-060', 'Recurso Procesal', 'Derecho Procesal', 'Medios de Impugnación', 'Acto jurídico procesal de la parte agraviada, ejercido mediante el cual impugna formalmente una resolución judicial no ejecutoriada, solicitando su revisión para anularla, modificarla o revocarla,.', 'El litigante perdidoso apela el fallo condenatorio de primera instancia para que la Corte de Apelaciones respectiva lo revise en el fondo,.', 'Doctrina Procesal (Mosquera / Maturana)', '', '', '["Exige de forma ineludible la existencia de un agravio o perjuicio directo causado al interviniente por la decisión del tribunal,.", "Constituyen el pilar fundamental que da vida y materializa la garantía procedimental de la doble instancia judicial."]')
